<template>
  <view class="page">
    <view class="campus-brand"><text>{{ labels.brand }}</text></view>
    <view class="head"><text class="title">{{ labels.title }}</text><text class="subtitle">{{ labels.subtitle }}</text></view>
    <view class="form card"><text class="label">{{ labels.name }}</text><input class="input" :placeholder="labels.namePlaceholder" v-model="form.name"/><text class="label">{{ labels.desc }}</text><textarea class="textarea" :placeholder="labels.descPlaceholder" v-model="form.desc"/><text class="label">{{ labels.start }}</text><picker mode="date" @change="form.startAt=$event.detail.value"><view class="input">{{ form.startAt || labels.startPlaceholder }}</view></picker><text class="label">{{ labels.end }}</text><picker mode="date" @change="form.endAt=$event.detail.value"><view class="input">{{ form.endAt || labels.endPlaceholder }}</view></picker><text class="label">{{ labels.location }}</text><input class="input" :placeholder="labels.locationPlaceholder" v-model="form.location"/><text class="label">{{ labels.reward }}</text><input class="input" type="number" placeholder="0" v-model="form.reward"/></view>
    <view class="primary-btn submit" @tap="submit">{{ labels.submit }}</view>
  </view>
</template>
<script>
import { callCloud } from '../../common/cloud.js'
import { toast } from '../../common/mock.js'
const labels = { brand: '\u6821\u56ed\u78b3\u4e2d\u548c\u7ba1\u7406\u7cfb\u7edf', title: '\u521b\u5efa\u5b98\u65b9\u6d3b\u52a8', subtitle: '\u586b\u5199\u6d3b\u52a8\u8be6\u60c5\uff0c\u53d1\u5e03\u65b0\u7684\u6821\u56ed\u73af\u4fdd\u5021\u8bae\u3002', name: '\u6d3b\u52a8\u540d\u79f0', namePlaceholder: '\u4f8b\u5982\uff1a\u6625\u5b63\u6821\u56ed\u690d\u6811\u8282', desc: '\u6d3b\u52a8\u8be6\u7ec6\u5185\u5bb9', descPlaceholder: '\u8bf7\u586b\u5199\u6d3b\u52a8\u89c4\u5219\u3001\u53c2\u4e0e\u65b9\u5f0f\u548c\u51ed\u8bc1\u8981\u6c42', start: '\u6d3b\u52a8\u5f00\u59cb\u65e5\u671f', startPlaceholder: '\u8bf7\u9009\u62e9\u5f00\u59cb\u65e5\u671f', end: '\u6d3b\u52a8\u622a\u6b62\u65e5\u671f', endPlaceholder: '\u8bf7\u9009\u62e9\u622a\u6b62\u65e5\u671f', location: '\u6d3b\u52a8\u5730\u70b9', locationPlaceholder: '\u9009\u62e9\u6216\u8f93\u5165\u5730\u70b9', reward: '\u78b3\u79ef\u5206\u5956\u52b1', submit: '\u53d1\u5e03\u5b98\u65b9\u6d3b\u52a8' }
export default { data() { return { labels, form: { name: '', desc: '', startAt: '', endAt: '', location: '', reward: '' } } }, methods: { async submit() { if (!this.form.name || !this.form.desc || !this.form.startAt || !this.form.endAt) return toast('\u8bf7\u5b8c\u6574\u586b\u5199\u6d3b\u52a8\u540d\u79f0\u3001\u8be6\u7ec6\u5185\u5bb9\u548c\u65e5\u671f'); try { await callCloud('activity-create', { title: this.form.name, desc: this.form.desc, startAt: this.form.startAt, endAt: this.form.endAt, date: this.form.startAt, location: this.form.location, reward: Number(this.form.reward || 0), organizerId: uni.getStorageSync('user_session')?.id || 'campus_demo', organizerType: 'campus', schoolId: uni.getStorageSync('user_school_id') || 'school_001' }); toast('\u5b98\u65b9\u6d3b\u52a8\u5df2\u53d1\u5e03'); setTimeout(() => uni.navigateBack(), 500) } catch (error) { toast(error.message || '\u53d1\u5e03\u5931\u8d25') } } } }
</script>
<style lang="scss">@import '../../common/portal.scss';.campus-brand{padding:18rpx 0 28rpx;color:#277a43;font-size:25rpx;font-weight:700}.head{padding:28rpx 4rpx}.form{padding:30rpx}.label{display:block;margin:24rpx 0 12rpx;color:#53615f;font-size:24rpx}.input,.textarea{width:100%;padding:0 24rpx;border-radius:20rpx;background:#f1f4f3;box-sizing:border-box}.input{height:94rpx;line-height:94rpx}.textarea{height:220rpx;padding-top:24rpx}.submit{margin-top:32rpx}</style>
